import json, requests
from databricks.sdk import WorkspaceClient

w = WorkspaceClient()
host = w.config.host.rstrip('/')
token = dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiToken().get()
headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}

results = {}

# Try creating online table with different sync type (Synced Tables)
paths_to_try = [
    "/api/2.0/online-tables",
]

# Try with run_continuously (synced table style)
payloads = {
    "run_continuously": {
        "name": "workspace.mlpab62f111.accountse81ff1_online",
        "spec": {
            "source_table_full_name": "workspace.mlpab62f111.accountse81ff1",
            "primary_key_columns": ["row_id"],
            "timeseries_key": "updated_at",
            "run_continuously": {}
        }
    },
    "run_triggered": {
        "name": "workspace.mlpab62f111.accountse81ff1_online",
        "spec": {
            "source_table_full_name": "workspace.mlpab62f111.accountse81ff1",
            "primary_key_columns": ["row_id"],
            "timeseries_key": "updated_at",
            "run_triggered": {}
        }
    }
}

for payload_name, payload in payloads.items():
    for path in paths_to_try:
        url = f"{host}{path}"
        r = requests.post(url, headers=headers, json=payload, timeout=10)
        results[f"{payload_name} {path}"] = {"status_code": r.status_code, "response": r.text[:300]}

# Try feature_engineering Python client
try:
    from databricks.feature_engineering import FeatureEngineeringClient
    fe = FeatureEngineeringClient()
    results['fe_client'] = "FeatureEngineeringClient available"
    results['fe_methods'] = [m for m in dir(fe) if not m.startswith('_') and 'online' in m.lower() or 'sync' in m.lower()]
except ImportError as e:
    results['fe_import_error'] = str(e)

dbutils.notebook.exit(json.dumps(results))

